glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 v_uv;
out vec4 v_color;
vec4 vert () {
  vec4 pos = vec4(a_position, 1.0);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  v_uv = a_texCoord;
  v_color = a_color;
  return cc_matViewProj * pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision mediump float;
in vec2 v_uv;
in vec4 v_color;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform ShockWaveParams {
  vec4 waveA0;
  vec4 waveA1;
  vec4 waveA2;
  vec4 waveB0;
  vec4 waveB1;
  vec4 waveB2;
  vec2 resolution;
  float waveCount;
  float enabled;
};
vec2 calcWaveOffset(vec2 uv, float aspect, vec4 waveA, vec4 waveB) {
  vec2 shockCenter = waveA.xy;
  float currentRadius = waveA.z;
  float ringWidth = waveA.w;
  float distortionStrength = waveB.x;
  float outroProgress = waveB.y;
  vec2 centered = uv - shockCenter;
  centered.x *= aspect;
  float dist = length(centered);
  float halfWidth = max(ringWidth * 0.5, 0.0001);
  float ringMask = 1.0 - smoothstep(0.0, halfWidth, abs(dist - currentRadius));
  vec2 dir = centered / max(dist, 0.0001);
  dir.x /= aspect;
  float distortionFade = 1.0 - smoothstep(0.0, 1.0, clamp(outroProgress, 0.0, 1.0));
  float offsetAmount = ringMask * distortionStrength * distortionFade;
  return dir * offsetAmount;
}
vec4 frag () {
  if (enabled < 0.5) {
    return texture(cc_spriteTexture, v_uv) * v_color;
  }
  vec2 totalOffset = vec2(0.0, 0.0);
  float aspect = resolution.x / max(resolution.y, 0.0001);
  if (waveCount > 0.5) {
    totalOffset += calcWaveOffset(v_uv, aspect, waveA0, waveB0);
  }
  if (waveCount > 1.5) {
    totalOffset += calcWaveOffset(v_uv, aspect, waveA1, waveB1);
  }
  if (waveCount > 2.5) {
    totalOffset += calcWaveOffset(v_uv, aspect, waveA2, waveB2);
  }
  vec2 distortedUV = v_uv + totalOffset;
  distortedUV = clamp(distortedUV, vec2(0.0, 0.0), vec2(1.0, 1.0));
  vec4 color = texture(cc_spriteTexture, distortedUV);
  return color * v_color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

